const body = $input.all()[0].json.body;
const args = body.message?.toolCalls?.[0]?.function?.arguments || {};
const toolCallId = body.message?.toolCalls?.[0]?.id || "";

const raison_transfert = args.raison_transfert || "Non spécifiée";

// Infos du patient depuis le message Vapi
const nom = args.nom || "Patient inconnu";
const telephone = args.telephone || "";

// Formater le téléphone
let tel = telephone.replace(/\D/g, "");
if (tel.length === 10) tel = "+1" + tel;
else if (tel.length === 11 && tel.startsWith("1")) tel = "+" + tel;
else if (!tel.startsWith("+")) tel = "+1" + tel;

// Créer un créneau dans 30 min pour le rappel
const now = new Date();
const debut = new Date(now.getTime() + 30 * 60000);
const fin = new Date(debut.getTime() + 15 * 60000);

const pad = (n) => String(n).padStart(2, "0");
const debutISO = `${debut.getFullYear()}-${pad(debut.getMonth()+1)}-${pad(debut.getDate())}T${pad(debut.getHours())}:${pad(debut.getMinutes())}:00`;
const finISO = `${fin.getFullYear()}-${pad(fin.getMonth()+1)}-${pad(fin.getDate())}T${pad(fin.getHours())}:${pad(fin.getMinutes())}:00`;

return [{
 json: {
 raison_transfert,
 nom,
 telephone: tel,
 debut: debutISO,
 fin: finISO,
 toolCallId
 }
}];
